func init() {
	embeddedDrizzleMigrationSnapshot = deriveEmbeddedDrizzleMigrationSnapshot(embeddedDrizzleMigrations)
}

func deriveEmbeddedDrizzleMigrationSnapshot(migrations []embeddedDrizzleMigration) []drizzleMigrationSnapshotEntry {
	snapshot := make([]drizzleMigrationSnapshotEntry, 0, len(migrations))
	for _, migration := range migrations {
		snapshot = append(snapshot, drizzleMigrationSnapshotEntry{
			Tag:  migration.Tag,
			When: migration.When,
			Hash: migration.Hash,
		})
	}
	return snapshot
}
